// @ts-nocheck
// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// Vote games: a card shows a scenario with two sides, everyone votes at once, then the room sees the split.
// Cards with a right answer (Did That Happen) score the players who got it right; opinion cards (Who's Wrong,
// Icks, Ultimatums) score everyone who sided with the majority, so the game is reading the room.
import { shuffle } from "../rng";
import type { VoteCard } from "../party/decks";

export type Side = "a" | "b";
export const VOTE_MS = 40_000;
export const REVEAL_MS = 9_000;

export type VoteState = {
  players: string[];
  deck: string;
  cards: VoteCard[];
  round: number;
  phase: "vote" | "reveal";
  /** This card's votes. Others only see that someone voted until the reveal. */
  votes: Record<string, Side>;
  /** Every finished card: the votes and which side scored. */
  history: { votes: Record<string, Side>; scored: Side | null }[];
  points: Record<string, number>;
  phaseAt: number;
  done: boolean;
};

export function init(o: { players: string[]; deck: string; cards: VoteCard[]; rounds: number; avoid?: string[]; seed: number; now: number }): VoteState {
  const avoid = new Set(o.avoid ?? []);
  const fresh = o.cards.filter((c) => !avoid.has(c.id));
  const [picked] = shuffle(fresh.length >= o.rounds ? fresh : o.cards, o.seed);
  const cards = picked.slice(0, Math.max(3, Math.min(15, o.rounds)));
  return { players: o.players, deck: o.deck, cards, round: 0, phase: "vote", votes: {}, history: [], points: Object.fromEntries(o.players.map((p) => [p, 0])), phaseAt: o.now, done: cards.length === 0 };
}

/** Which side scores: the right answer if the card has one, otherwise the majority (a tie scores nobody). */
export function scoringSide(card: VoteCard, votes: Record<string, Side>): Side | null {
  if (card.answer) return card.answer;
  const a = Object.values(votes).filter((v) => v === "a").length, b = Object.values(votes).filter((v) => v === "b").length;
  return a === b ? null : a > b ? "a" : "b";
}

function reveal(s: VoteState, now: number): VoteState {
  const scored = scoringSide(s.cards[s.round]!, s.votes);
  const points = { ...s.points };
  if (scored) for (const [p, v] of Object.entries(s.votes)) if (v === scored) points[p] = (points[p] ?? 0) + 1;
  return { ...s, phase: "reveal", points, history: [...s.history, { votes: s.votes, scored }], phaseAt: now };
}

function advance(s: VoteState, now: number): VoteState {
  const round = s.round + 1;
  return round >= s.cards.length ? { ...s, done: true, phaseAt: now } : { ...s, round, phase: "vote", votes: {}, phaseAt: now };
}

export function vote(s: VoteState, by: string, side: string, now: number): VoteState {
  if (s.done || s.phase !== "vote" || (side !== "a" && side !== "b") || s.votes[by]) return s;
  const next = { ...s, votes: { ...s.votes, [by]: side as Side } };
  return Object.keys(next.votes).length >= s.players.length ? reveal(next, now) : next;
}

/** Anyone can skip ahead from a reveal once they have read it. */
export function nextCard(s: VoteState, now: number): VoteState {
  return s.done || s.phase !== "reveal" ? s : advance(s, now);
}

export function tick(s: VoteState, now: number): VoteState {
  if (s.done) return s;
  if (s.phase === "vote" && now - s.phaseAt > VOTE_MS) return reveal(s, now);
  if (s.phase === "reveal" && now - s.phaseAt > REVEAL_MS) return advance(s, now);
  return s;
}

export function redactFor(s: VoteState, me: string | null): VoteState {
  if (s.done || s.phase !== "vote") return s;
  return { ...s, votes: Object.fromEntries(Object.entries(s.votes).map(([k, v]) => [k, (k === me ? v : "?") as Side])) };
}
